class Auto(object):
    """Specifier type that represents a value to be automatically filled
    in based on context."""
    def __repr__(self):
        return 'Auto()'


class Fill(object):
    """Specifier type for filling in values from data."""
    def __init__(self, spec=None, **kwargs):
        self.spec = spec
        self.kwargs = kwargs

    def __repr__(self):
        cn = self.__class__.__name__
        parts = []
        if self.spec is not None:
            parts.append('spec=%r' % self.spec)
        for k, v in sorted(self.kwargs.items()):
            parts.append('%s=%r' % (k, v))
        if not parts:
            return '%s()' % cn
        return '%s(%s)' % (cn, ', '.join(parts))


class Iter(object):
    """Specifier type for iterating over a target."""
    def __init__(self, spec=None):
        self.spec = spec

    def __repr__(self):
        cn = self.__class__.__name__
        if self.spec is not None:
            return '%s(%r)' % (cn, self.spec)
        return '%s()' % cn


class Let(object):
    """Specifier type for binding variables in the scope."""
    def __init__(self, **bindings):
        self.bindings = bindings

    def __repr__(self):
        cn = self.__class__.__name__
        if not self.bindings:
            return '%s()' % cn
        parts = ['%s=%r' % (k, v) for k, v in sorted(self.bindings.items())]
        return '%s(%s)' % (cn, ', '.join(parts))


class ROOTType(object):
    """Singleton representing the root of the target."""
    _instance = None
    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(ROOTType, cls).__new__(cls)
        return cls._instance
    def __repr__(self):
        return 'ROOT'


ROOT = ROOTType()


class Invoke(object):
    """Specifier type for invoking callables with constant arguments."""
    def __init__(self, func, *args, **kwargs):
        self.func = func
        self.constants = args
        self._kwargs = kwargs

    def __repr__(self):
        cn = self.__class__.__name__
        parts = [repr(self.func)]
        if self.constants:
            parts.extend([repr(c) for c in self.constants])
        if self._kwargs:
            for k, v in sorted(self._kwargs.items()):
                parts.append('%s=%r' % (k, v))
        return '%s(%s)' % (cn, ', '.join(parts))


_DEFAULT_SCOPE.update({
    glom: _glom,
    TargetRegistry: TargetRegistry(register_default_types=True),
    Auto: Auto,
    Fill: Fill,
    Iter: Iter,
    Let: Let,
    ROOT: ROOT,
    Invoke: Invoke,
})
